/* Error handling with goto (cleanup pattern) */
int process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        goto error;
    }

    char *buffer = malloc(1024);
    if (!buffer) {
        goto cleanup_file;
    }

    /* Process file... */

    free(buffer);
    fclose(file);
    return 0;  /* Success */

cleanup_file:
    fclose(file);
error:
    fprintf(stderr, "Error processing %s\\n", filename);
    return -1;  /* Failure */
}

